package com.ventas.service;
import com.ventas.dto.XmlTrialModels.*;import java.util.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.io.StringWriter;import javax.xml.stream.*;import org.springframework.stereotype.Component;
@Component public class XmlTrialRenderer{
 public static final String WARNING="DOCUMENTO DE PRUEBA - SIN FIRMA DIGITAL - SIN VALIDEZ TRIBUTARIA - NO ENVIADO A SUNAT";
 private static final String INVOICE="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2";private static final String CBC="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2";private static final String CAC="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2";
 private boolean text(String v,int max){return v!=null&&!v.isBlank()&&v.length()<=max&&v.codePoints().allMatch(cp->cp==9||cp==10||cp==13||cp>=32&&cp<=0xD7FF||cp>=0xE000&&cp<=0xFFFD||cp>=0x10000&&cp<=0x10FFFF);}
 private boolean money(BigDecimal n,boolean positive){return n!=null&&(positive?n.signum()>0:n.signum()>=0)&&n.scale()<=2;}
 public List<String> errors(Document d){var e=new ArrayList<String>();if(!Set.of("B","F").contains(Objects.toString(d.tipo(),"")))e.add("Solo se preparan boletas y facturas; la nota de venta no es un documento electrónico UBL de este laboratorio.");if(!"CONFIRMADA".equals(d.estadoVenta())||!"EMITIDO".equals(d.estadoComprobante()))e.add("Se requiere una venta confirmada y un comprobante sin anular.");if(!"NO_INTEGRADO".equals(d.estadoTributario()))e.add("El laboratorio solo admite comprobantes no integrados.");if(d.serie()==null||!d.serie().matches("[BF][0-9]{3}")||!d.serie().startsWith(Objects.toString(d.tipo(),"?"))||d.numero()<1||d.fecha()==null)e.add("Revisa la serie, número y fecha guardados.");if(!text(d.emisor(),150)||d.ruc()==null||!d.ruc().matches("(10|20)[0-9]{9}")||!text(d.direccion(),200))e.add("El comprobante guardado necesita nombre, RUC y dirección del emisor.");if(!text(d.cliente(),150))e.add("Falta el nombre del cliente.");boolean identified=d.documento()!=null&&!d.documento().isBlank();if(identified&&!("DNI".equals(d.tipoDocumento())&&d.documento().matches("(?!00000000)[0-9]{8}")||"RUC".equals(d.tipoDocumento())&&d.documento().matches("(10|20)[0-9]{9}")))e.add("El documento del cliente no es válido para este borrador.");if("F".equals(d.tipo())&&(!identified||!"RUC".equals(d.tipoDocumento())))e.add("La factura requiere un cliente identificado con RUC.");if(d.porcentaje()==null||d.porcentaje().signum()<=0||d.porcentaje().compareTo(new BigDecimal("30"))>0)e.add("Esta etapa admite únicamente operaciones gravadas con IGV positivo.");if(!money(d.base(),true)||!money(d.igv(),false)||!money(d.total(),true)||d.base()!=null&&d.igv()!=null&&d.total()!=null&&d.base().add(d.igv()).compareTo(d.total())!=0)e.add("Los totales del comprobante no concilian.");if(d.porcentaje()!=null&&d.porcentaje().signum()>0&&d.base()!=null&&d.total()!=null&&d.base().compareTo(d.total().divide(BigDecimal.ONE.add(d.porcentaje().divide(new BigDecimal("100"))),2,RoundingMode.HALF_UP))!=0)e.add("La base imponible no corresponde al porcentaje de IGV guardado.");if(d.lineas()==null||d.lineas().isEmpty()||d.lineas().size()>500){e.add("Se requieren entre 1 y 500 líneas.");return e;}BigDecimal base=BigDecimal.ZERO,igv=BigDecimal.ZERO,total=BigDecimal.ZERO;var ids=new HashSet<Long>();for(var l:d.lineas()){boolean valid=text(l.producto(),120)&&text(l.presentacion(),60)&&l.unidad()!=null&&l.unidad().matches("[A-Z0-9]{2,3}")&&l.cantidad()!=null&&l.cantidad().signum()>0&&l.cantidad().scale()<=6&&l.precio()!=null&&l.precio().signum()>0&&l.precio().scale()<=6&&money(l.importe(),true)&&money(l.base(),false)&&money(l.igv(),false)&&ids.add(l.id());if(!valid){e.add("La línea "+l.id()+" tiene datos incompletos o fuera de los límites.");continue;}if(l.base().add(l.igv()).compareTo(l.importe())!=0||l.cantidad().multiply(l.precio()).setScale(2,RoundingMode.HALF_UP).compareTo(l.importe())!=0)e.add("Los importes de la línea "+l.id()+" no concilian.");base=base.add(l.base());igv=igv.add(l.igv());total=total.add(l.importe());}if(d.base()!=null&&d.igv()!=null&&d.total()!=null&&(base.compareTo(d.base())!=0||igv.compareTo(d.igv())!=0||total.compareTo(d.total())!=0))e.add("La suma de las líneas no coincide con los totales guardados.");return e;}
 public Preview preview(Document d){var errors=errors(d);var notes=new ArrayList<>(List.of(WARNING,"Borrador local basado en UBL 2.1. No validado contra el XSD completo ni las reglas tributarias de SUNAT.","Faltan firma digital, validación fiscal y datos adicionales del emisor para una futura integración."));if(d.documento()==null||d.documento().isBlank())notes.add("Boleta sin documento: se omite la identificación del cliente; queda pendiente su validación con el integrador fiscal.");return new Preview("LOCAL_SIN_FIRMA",false,false,errors.isEmpty(),d.serie()+"-"+d.numero(),errors,notes,errors.isEmpty()?render(d):null);}
 private String amount(BigDecimal n){return n.setScale(2,RoundingMode.HALF_UP).toPlainString();}
 private void start(XMLStreamWriter w,String prefix,String name)throws XMLStreamException{w.writeStartElement(prefix,name,prefix.equals("cac")?CAC:CBC);}
 private void value(XMLStreamWriter w,String name,String value)throws XMLStreamException{start(w,"cbc",name);w.writeCharacters(value);w.writeEndElement();}
 private void money(XMLStreamWriter w,String name,BigDecimal value)throws XMLStreamException{start(w,"cbc",name);w.writeAttribute("currencyID","PEN");w.writeCharacters(amount(value));w.writeEndElement();}
 private void party(XMLStreamWriter w,String tag,String name,String doc,String scheme,String address)throws XMLStreamException{start(w,"cac",tag);start(w,"cac","Party");if(doc!=null&&!doc.isBlank()){start(w,"cac","PartyIdentification");start(w,"cbc","ID");w.writeAttribute("schemeID",scheme);w.writeCharacters(doc);w.writeEndElement();w.writeEndElement();}start(w,"cac","PartyLegalEntity");value(w,"RegistrationName",name);if(address!=null){start(w,"cac","RegistrationAddress");start(w,"cac","AddressLine");value(w,"Line",address);w.writeEndElement();start(w,"cac","Country");value(w,"IdentificationCode","PE");w.writeEndElement();w.writeEndElement();}w.writeEndElement();w.writeEndElement();w.writeEndElement();}
 private void tax(XMLStreamWriter w,BigDecimal base,BigDecimal igv,BigDecimal percent)throws XMLStreamException{start(w,"cac","TaxTotal");money(w,"TaxAmount",igv);start(w,"cac","TaxSubtotal");money(w,"TaxableAmount",base);money(w,"TaxAmount",igv);start(w,"cac","TaxCategory");value(w,"ID","S");value(w,"Percent",percent.stripTrailingZeros().toPlainString());value(w,"TaxExemptionReasonCode","10");start(w,"cac","TaxScheme");value(w,"ID","1000");value(w,"Name","IGV");value(w,"TaxTypeCode","VAT");w.writeEndElement();w.writeEndElement();w.writeEndElement();w.writeEndElement();}
 private String render(Document d){try{var out=new StringWriter();var w=XMLOutputFactory.newFactory().createXMLStreamWriter(out);w.writeStartDocument("UTF-8","1.0");w.writeStartElement("","Invoice",INVOICE);w.writeDefaultNamespace(INVOICE);w.writeNamespace("cac",CAC);w.writeNamespace("cbc",CBC);value(w,"UBLVersionID","2.1");value(w,"CustomizationID","2.0");value(w,"ID",d.serie()+"-"+d.numero());value(w,"IssueDate",d.fecha().toLocalDate().toString());value(w,"IssueTime",d.fecha().toLocalTime().format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss")));start(w,"cbc","InvoiceTypeCode");w.writeAttribute("listID","0101");w.writeCharacters(d.tipo().equals("F")?"01":"03");w.writeEndElement();value(w,"Note",WARNING);value(w,"DocumentCurrencyCode","PEN");value(w,"LineCountNumeric",String.valueOf(d.lineas().size()));party(w,"AccountingSupplierParty",d.emisor(),d.ruc(),"6",d.direccion());party(w,"AccountingCustomerParty",d.cliente(),d.documento(),"RUC".equals(d.tipoDocumento())?"6":"1",null);tax(w,d.base(),d.igv(),d.porcentaje());start(w,"cac","LegalMonetaryTotal");money(w,"LineExtensionAmount",d.base());money(w,"TaxInclusiveAmount",d.total());money(w,"PayableAmount",d.total());w.writeEndElement();int index=0;for(var l:d.lineas()){start(w,"cac","InvoiceLine");value(w,"ID",String.valueOf(++index));start(w,"cbc","InvoicedQuantity");w.writeAttribute("unitCode",l.unidad());w.writeCharacters(l.cantidad().stripTrailingZeros().toPlainString());w.writeEndElement();money(w,"LineExtensionAmount",l.base());start(w,"cac","PricingReference");start(w,"cac","AlternativeConditionPrice");start(w,"cbc","PriceAmount");w.writeAttribute("currencyID","PEN");w.writeCharacters(l.precio().stripTrailingZeros().toPlainString());w.writeEndElement();value(w,"PriceTypeCode","01");w.writeEndElement();w.writeEndElement();tax(w,l.base(),l.igv(),d.porcentaje());start(w,"cac","Item");value(w,"Description",l.producto()+" · "+l.presentacion());w.writeEndElement();start(w,"cac","Price");start(w,"cbc","PriceAmount");w.writeAttribute("currencyID","PEN");w.writeCharacters(l.base().divide(l.cantidad(),10,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString());w.writeEndElement();w.writeEndElement();w.writeEndElement();}w.writeEndElement();w.writeEndDocument();w.close();return out.toString();}catch(XMLStreamException e){throw new IllegalStateException("No se pudo construir el XML de prueba");}}
}
